package com.safebaba.controller;
import com.safebaba.model.Usuario; import com.safebaba.service.UsuarioService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/usuarios") public class UsuarioController { private final UsuarioService service; public UsuarioController(UsuarioService service){this.service=service;} @GetMapping("/{id}") public Object buscar(@PathVariable Long id, org.springframework.security.core.Authentication auth){Usuario u=service.buscar(id); boolean admin=auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ADMIN")); if(!admin&&!u.getEmail().equalsIgnoreCase(auth.getName())) throw new org.springframework.security.access.AccessDeniedException("Acesso negado.");return java.util.Map.of("id",u.getId(),"nome",u.getNome(),"email",u.getEmail(),"telefone",u.getTelefone(),"cidade",u.getCidade(),"estado",u.getEstado(),"tipo",u.getTipo());} }
